import {copyPath} from './flexible-parts.js';
import {copyMass} from './mass.js';
import {groundingReason,groundedParts} from './grounding.js';
import {V,Q,definition,component,ports,part,autoLinks} from './engine.js';
import {axleInfo} from './motion.js';
let serial=0;
export function sanitizeEditor(value,validIds){const clean={layers:[],groups:[]},usedLayers=new Set(),usedGroups=new Set();for(const key of['layers','groups']){const names=new Set();for(const item of(Array.isArray(value?.[key])?value[key]:[]).slice(0,200)){if(!item||typeof item.id!=='string'||item.id.length>100||names.has(item.id))continue;names.add(item.id);const used=key==='layers'?usedLayers:usedGroups,partIds=[...new Set((Array.isArray(item.partIds)?item.partIds:[]).filter(id=>validIds.has(id)&&!used.has(id)))];partIds.forEach(id=>used.add(id));clean[key].push({id:item.id,name:typeof item.name==='string'?item.name.slice(0,60):key==='layers'?'Layer':'Group',partIds,...(key==='layers'?{visible:item.visible!==false,locked:item.locked===true}:{})});}}return clean;}
export function editorState(m){return m.editor??={layers:[],groups:[]};}
export function layerFor(m,id){return m.editor?.layers.find(l=>l.partIds.includes(id));}
export function visiblePart(m,id,isolated=null){return layerFor(m,id)?.visible!==false&&(!isolated||isolated.has(id));}
export function selectablePart(m,id,isolated=null){return visiblePart(m,id,isolated)&&!layerFor(m,id)?.locked;}
export function groupFor(m,id){return m.editor?.groups.find(g=>g.partIds.includes(id));}
export function makeGroup(m,ids,name='Group'){const e=editorState(m),valid=new Set(m.parts.map(p=>p.id)),selected=[...new Set(ids)].filter(id=>valid.has(id));if(!selected.length)throw Error('Select parts first.');for(const g of e.groups)g.partIds=g.partIds.filter(id=>!selected.includes(id));e.groups=e.groups.filter(g=>g.partIds.length);const g={id:'group-'+Date.now().toString(36)+'-'+ ++serial,name:name.trim().slice(0,60)||'Group',partIds:selected};e.groups.push(g);return g;}
export function makeLayer(m,ids,name='Layer'){const e=editorState(m),selected=[...new Set(ids)].filter(id=>m.parts.some(p=>p.id===id));for(const l of e.layers)l.partIds=l.partIds.filter(id=>!selected.includes(id));const l={id:'layer-'+Date.now().toString(36)+'-'+ ++serial,name:name.trim().slice(0,60)||'Layer',partIds:selected,visible:true,locked:false};e.layers.push(l);return l;}
export function selectionClosure(m,ids){const result=new Set();for(const id of ids)if(m.parts.some(p=>p.id===id))for(const p of component(m,id))result.add(p);return result;}
export function editBlockReason(m,ids){return groundingReason(m,ids)||([...ids].some(id=>layerFor(m,id)?.locked)?'Connected parts are on a locked layer. Unlock it before transforming.':'');}
export function editable(m,ids){return !editBlockReason(m,ids);}
export function duplicateSelection(m,ids){const selected=new Set(ids),map=new Map(),batch=[];if(m.parts.length+selected.size>2500)throw Error('Maximum 2500 parts per model.');for(const p of m.parts.filter(p=>selected.has(p.id))){const n=part(p.type,V(p.pos).add(V([0,0,60])).toArray(),p.quat);copyMass(p,n);copyPath(p,n);map.set(p.id,n.id);batch.push(n);}m.links.push(...m.links.filter(l=>selected.has(l.a)&&selected.has(l.b)).map(l=>({...l,a:map.get(l.a),b:map.get(l.b)})));m.parts.push(...batch);if(m.controller)m.controller.push(...m.controller.filter(c=>map.has(c.motorId)).map(c=>({...c,motorId:map.get(c.motorId)})));const copies=[...map.values()];makeGroup(m,copies,'Copy');return copies;}
export function rotatePlan(m,id){const p=m.parts.find(p=>p.id===id);if(!p)throw Error('Select a part.');const axle=axleInfo(m,id);if(axle.available&&axle.boundary.length)return {...axle,kind:'axle',label:'Axle'};
 if(definition(p).group==='connectors'){const options=[];for(const l of m.links.filter(l=>l.mode==='end'&&(l.a===id||l.b===id))){const ids=component({...m,links:m.links.filter(x=>x!==l)},id),other=l.a===id?l.b:l.a;if(ids.has(other))continue;const port=ports(p).find(t=>t.key===(l.a===id?l.ap:l.bp));if(port)options.push({ids,axis:port.dir,origin:port.pos,kind:'pivot',label:'Socket pivot'});}if(options.length)return options.sort((a,b)=>Number(!!groundedParts(m,a.ids).length)-Number(!!groundedParts(m,b.ids).length)||a.ids.size-b.ids.size)[0];}
 return {ids:component(m,id),axis:V([0,0,1]).applyQuaternion(Q(p.quat)).toArray(),origin:p.pos,kind:'assembly',label:'Assembly'};
}
// Screen-space snap radius stays usable at every zoom level. Retain the current
// target until another is clearly closer, avoiding flicker in dense connectors.
export function magneticTarget(candidates,pointer,{previous=null,radius=22,cycle=0}={}){const near=candidates.map(c=>({...c,distance:Math.hypot(c.x-pointer.x,c.y-pointer.y)})).filter(c=>c.depth>=-1&&c.depth<=1&&c.distance<=radius*(c.id===previous?1.4:1)).sort((a,b)=>a.distance-b.distance||a.depth-b.depth);if(!near.length)return null;if(cycle)return near[((cycle%near.length)+near.length)%near.length];const held=near.find(c=>c.id===previous);return held&&held.distance<=near[0].distance+6?held:near[0];}
export function snappedAngle(value,{fine=false,free=false}={}){return free?value:Math.round(value/(fine?15:45))*(fine?15:45);}

export function rotationPlanForSelection(m,selection){const ids=new Set(selection),id=[...ids][0];if(!id)return null;const joint=rotatePlan(m,id);if([...ids].every(id=>joint.ids.has(id)))return joint;const p=m.parts.find(p=>p.id===id);return{ids:selectionClosure(m,ids),origin:p.pos,axis:[0,1,0],kind:'assembly',label:'Selected assemblies'};}
export function selectionMotionPlan(m,selection,mode='auto'){const ids=new Set(selection);if(!ids.size)return null;const joint=rotationPlanForSelection(m,ids),p=m.parts.find(p=>p.id===[...ids][0]);if(joint.kind==='axle')return{...joint,mode:mode==='rotate'?'pivot':'axle'};if(joint.kind==='pivot'&&mode!=='move')return{...joint,mode:'pivot'};return{...joint,ids:selectionClosure(m,ids),origin:p.pos,kind:'assembly',label:mode==='rotate'?'Rotate assembly':'Move assembly',mode:mode==='rotate'?'rotate':'move'};}
